-- Database tecnico Vatia: 128 alimenti, valori per 100 g.
-- Generato da src/data/foods.ts; eseguibile più volte senza duplicati.
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  note = excluded.note,
  per100g = excluded.per100g,
  source = excluded.source,
  is_public = excluded.is_public;
